package com.personal.assistant.module.reminder.service;
import com.personal.assistant.common.security.JwtProperties;import org.springframework.stereotype.Service;import javax.crypto.*;import javax.crypto.spec.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;
@Service public class SecretCryptoService {private final SecretKeySpec key;public SecretCryptoService(JwtProperties p){try{byte[] k=MessageDigest.getInstance("SHA-256").digest(p.getSecret().getBytes(StandardCharsets.UTF_8));key=new SecretKeySpec(k,"AES");}catch(Exception e){throw new IllegalStateException(e);}}public String encrypt(String plain){try{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key,new GCMParameterSpec(128,iv));byte[] data=c.doFinal(plain.getBytes(StandardCharsets.UTF_8));byte[] all=new byte[iv.length+data.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(data,0,all,iv.length,data.length);return Base64.getEncoder().encodeToString(all);}catch(Exception e){throw new IllegalStateException("敏感配置加密失败",e);}}public String decrypt(String encoded){try{byte[] all=Base64.getDecoder().decode(encoded);byte[] iv=Arrays.copyOfRange(all,0,12),data=Arrays.copyOfRange(all,12,all.length);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,iv));return new String(c.doFinal(data),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("敏感配置解密失败",e);}}}